options.helpers:
context.handlebars.registerHelper('evidenceRows', rows => {
  for (const row of Array.isArray(rows) ? rows : []) {
    let record;
    try { record = JSON.parse(row.Line || row.line || row.body || '{}'); } catch (_) { continue; }
    if (record.event !== 'crowdsec_alert') continue;
    const events = ((record.alert || {}).events || []).map(event => {
      const fields = Object.fromEntries((event.meta || []).map(item => [item.key, item.value]));
      return {method: fields.http_verb || '', path: fields.http_path || 'Path unavailable', status: fields.http_status || 'Unknown', site: fields.nginx_site === '_' ? 'Catch-all' : fields.nginx_site || 'Unknown', time: fields.timestamp || event.timestamp};
    });
    return [{...record, siteLabel: (record.sites || ['Unknown']).map(site => site === '_' ? 'Catch-all' : site).join(', '), startLabel: new Date(record.start_at).toLocaleString(), stopLabel: new Date(record.stop_at).toLocaleString(), events}];
  }
  return [];
});
